  "8": [{"jp":"父は自動車会社の**技術者**です。","vi":"Bố tôi là kỹ thuật viên ở công ty ô tô."},{"jp":"**技術者**が機械を直しました。","vi":"Kỹ thuật viên đã sửa máy."}],
  "9": [{"jp":"私はベトナムから来た**留学生**です。","vi":"Tôi là du học sinh đến từ Việt Nam."},{"jp":"この大学には**留学生**がたくさんいます。","vi":"Trường đại học này có nhiều du học sinh."}],
  "10": [{"jp":"私は**学生**です。","vi":"Tôi là học sinh."},{"jp":"あの**学生**は毎日図書館で勉強します。","vi":"Cậu học sinh kia ngày nào cũng học ở thư viện."}],
  "11": [{"jp":"兄は**会社員**です。","vi":"Anh trai tôi là nhân viên công ty."},{"jp":"田中さんはIMCの**社員**です。","vi":"Anh Tanaka là nhân viên của công ty IMC."}],
  "12": [{"jp":"姉は**銀行員**です。","vi":"Chị tôi là nhân viên ngân hàng."},{"jp":"**銀行員**の仕事は大変です。","vi":"Công việc của nhân viên ngân hàng rất vất vả."}],
  "13": [{"jp":"父は**医者**です。","vi":"Bố tôi là bác sĩ."},{"jp":"熱があるので、**医者**に行きます。","vi":"Vì bị sốt nên tôi đi khám bác sĩ."}],
  "14": [{"jp":"兄は**大学**の学生です。","vi":"Anh trai tôi là sinh viên đại học."},{"jp":"私は東京の**大学**で勉強しています。","vi":"Tôi đang học ở một trường đại học ở Tokyo."}],
  "15": [{"jp":"この**機械**は日本製です。","vi":"Cái máy này do Nhật sản xuất."},{"jp":"工場で**機械**を使って働きます。","vi":"Tôi làm việc ở nhà máy, sử dụng máy móc."}],
  "16": [{"jp":"父は**自動車**の会社で働いています。","vi":"Bố tôi làm việc ở công ty ô tô."},{"jp":"日曜日に**車**で海へ行きます。","vi":"Chủ nhật tôi đi biển bằng ô tô."}],
  "17": [{"jp":"私の**専門**は機械です。","vi":"Chuyên môn của tôi là cơ khí."},{"jp":"大学で何を**専門**に勉強しましたか。","vi":"Ở đại học bạn đã học chuyên ngành gì?"}],
