  "20": [{"jp":"「**お名前は**？」「マイです。」","vi":"\"Tên bạn là gì?\" \"Tôi là Mai.\""},{"jp":"失礼ですが、**お名前は**？","vi":"Xin lỗi, tên anh là gì ạ?"}],
  "21": [{"jp":"**初めまして**。ミンです。どうぞよろしく。","vi":"Xin chào, rất vui được gặp. Tôi là Minh. Rất mong được giúp đỡ."},{"jp":"「**初めまして**。田中です。」「初めまして。」","vi":"\"Rất vui được gặp anh. Tôi là Tanaka.\" \"Rất vui được gặp anh.\""}],
  "22": [{"jp":"ワンさんは**中国**から来ました。","vi":"Anh Vương đến từ Trung Quốc."},{"jp":"**中国**の料理はおいしいです。","vi":"Món ăn Trung Quốc rất ngon."}],
  "23": [{"jp":"キムさんは**韓国**人です。","vi":"Anh Kim là người Hàn Quốc."},{"jp":"夏休みに**韓国**へ旅行します。","vi":"Kỳ nghỉ hè tôi sẽ đi du lịch Hàn Quốc."}],
  "24": [{"jp":"私は**ベトナム**から来ました。","vi":"Tôi đến từ Việt Nam."},{"jp":"**ベトナム**のフォーはとてもおいしいです。","vi":"Phở Việt Nam rất ngon."}],
  "25": [{"jp":"私は**日本**の会社で働いています。","vi":"Tôi đang làm việc ở công ty Nhật."},{"jp":"「がんばれ、**日本**！」とみんなが言いました。","vi":"Mọi người hô: \"Cố lên, Nhật Bản!\""}],
  "26": [{"jp":"あの人は**誰**ですか。","vi":"Người kia là ai vậy?"},{"jp":"これは**誰**の傘ですか。","vi":"Đây là ô của ai?"}],
  "27": [{"jp":"これは日本語の**本**です。","vi":"Đây là sách tiếng Nhật."},{"jp":"図書館で**本**を借りました。","vi":"Tôi đã mượn sách ở thư viện."}],
  "28": [{"jp":"これは**辞書**です。","vi":"Đây là từ điển."},{"jp":"わからない言葉は**辞書**で調べます。","vi":"Từ nào không hiểu thì tôi tra từ điển."}],
  "29": [{"jp":"これは車の**雑誌**です。","vi":"Đây là tạp chí về ô tô."},{"jp":"毎月、ファッション**雑誌**を買います。","vi":"Tháng nào tôi cũng mua tạp chí thời trang."}],
  "30": [{"jp":"父は毎朝**新聞**を読みます。","vi":"Bố tôi đọc báo mỗi sáng."},{"jp":"これは今日の**新聞**です。","vi":"Đây là báo hôm nay."}],
  "31": [{"jp":"**紙**に名前を書いてください。","vi":"Hãy viết tên vào giấy."},{"jp":"この**紙**は白いです。","vi":"Tờ giấy này màu trắng."}],
  "32": [{"jp":"父は**煙草**を吸いません。","vi":"Bố tôi không hút thuốc lá."},{"jp":"ここで**煙草**を吸わないでください。","vi":"Xin đừng hút thuốc ở đây."}],
  "33": [{"jp":"すみません、**灰皿**はありますか。","vi":"Xin lỗi, có gạt tàn không ạ?"},{"jp":"**灰皿**はテーブルの上にあります。","vi":"Gạt tàn ở trên bàn."}],
  "34": [{"jp":"この**箱**の中に何がありますか。","vi":"Trong hộp này có gì?"},{"jp":"大きい**箱**に本を入れました。","vi":"Tôi đã cho sách vào cái hộp to."}],
  "35": [{"jp":"母に**手紙**を書きます。","vi":"Tôi viết thư cho mẹ."},{"jp":"友達から**手紙**が来ました。","vi":"Tôi nhận được thư từ bạn."}],
  "36": [{"jp":"**手帳**に予定を書きます。","vi":"Tôi ghi lịch trình vào sổ tay."},{"jp":"これは私の**手帳**です。","vi":"Đây là sổ tay của tôi."}],
  "37": [{"jp":"これは私の**名刺**です。どうぞ。","vi":"Đây là danh thiếp của tôi. Xin mời."},{"jp":"初めて会った人と**名刺**を交換しました。","vi":"Tôi đã trao đổi danh thiếp với người mới gặp lần đầu."}],
  "38": [{"jp":"**鉛筆**で名前を書いてください。","vi":"Hãy viết tên bằng bút chì."},{"jp":"この**鉛筆**は誰のですか。","vi":"Cây bút chì này là của ai?"}],
  "39": [{"jp":"これは部屋の**鍵**です。","vi":"Đây là chìa khóa phòng."},{"jp":"**鍵**をかけて出かけました。","vi":"Tôi đã khóa cửa rồi ra ngoài."}],
  "40": [{"jp":"この**時計**は日本のです。","vi":"Chiếc đồng hồ này là của Nhật."},{"jp":"**時計**を見てください。もう9時です。","vi":"Hãy nhìn đồng hồ đi. Đã 9 giờ rồi."}],
  "41": [{"jp":"雨ですから、**傘**を持って行きます。","vi":"Vì trời mưa nên tôi mang ô theo."},{"jp":"これは誰の**傘**ですか。","vi":"Đây là ô của ai?"}],
  "42": [{"jp":"**鞄**の中に本があります。","vi":"Trong cặp có sách."},{"jp":"この**鞄**はとても高いです。","vi":"Cái cặp này rất đắt."}],
