  "44": [{"jp":"**携帯電話**で写真を撮りました。","vi":"Tôi đã chụp ảnh bằng điện thoại di động."},{"jp":"電車の中で**携帯電話**を使わないでください。","vi":"Xin đừng dùng điện thoại di động trên tàu."}],
  "45": [{"jp":"**机**の上に本があります。","vi":"Trên bàn có sách."},{"jp":"新しい**机**を買いました。","vi":"Tôi đã mua cái bàn mới."}],
  "46": [{"jp":"どうぞ、この**椅子**に座ってください。","vi":"Mời anh ngồi vào ghế này."},{"jp":"**椅子**の下に猫がいます。","vi":"Có con mèo ở dưới ghế."}],
  "47": [{"jp":"**窓**を開けてください。","vi":"Hãy mở cửa sổ ra."},{"jp":"**窓**から山が見えます。","vi":"Từ cửa sổ có thể nhìn thấy núi."}],
