  "55": [{"jp":"**会議室**は3階です。","vi":"Phòng họp ở tầng 3."},{"jp":"午後2時から**会議室**で会議があります。","vi":"Từ 2 giờ chiều có cuộc họp ở phòng họp."}],
  "56": [{"jp":"**受付**は1階です。","vi":"Quầy lễ tân ở tầng 1."},{"jp":"病院に着いたら、まず**受付**で名前を言ってください。","vi":"Khi đến bệnh viện, trước tiên hãy nói tên ở quầy tiếp tân."}],
