  "58": [{"jp":"**庭**に花がたくさんあります。","vi":"Trong vườn có nhiều hoa."},{"jp":"子どもたちが**庭**で遊んでいます。","vi":"Bọn trẻ đang chơi ngoài sân."}],
  "59": [{"jp":"**階段**で3階まで上ります。","vi":"Tôi đi cầu thang lên tầng 3."},{"jp":"**階段**はあちらです。","vi":"Cầu thang ở đằng kia."}],
  "60": [{"jp":"**お国**はどちらですか。","vi":"Anh đến từ nước nào ạ?"},{"jp":"私の**国**はベトナムです。","vi":"Đất nước của tôi là Việt Nam."}],
  "61": [{"jp":"父は**会社**で働いています。","vi":"Bố tôi làm việc ở công ty."},{"jp":"毎朝8時に**会社**へ行きます。","vi":"Mỗi sáng tôi đến công ty lúc 8 giờ."}],
  "62": [{"jp":"明日、友達が私の**家**に来ます。","vi":"Ngày mai bạn tôi sẽ đến nhà tôi."},{"jp":"6時に**家**へ帰ります。","vi":"Tôi về nhà lúc 6 giờ."}],
  "63": [{"jp":"新しい**靴**を買いました。","vi":"Tôi đã mua giày mới."},{"jp":"日本の家では**靴**を脱ぎます。","vi":"Ở nhà của người Nhật thì phải cởi giày."}],
  "64": [{"jp":"兄は毎日**煙草**を吸います。","vi":"Anh trai tôi ngày nào cũng hút thuốc lá."},{"jp":"この店では**煙草**を売っていません。","vi":"Cửa hàng này không bán thuốc lá."}],
  "65": [{"jp":"靴の**売り場**は3階です。","vi":"Quầy bán giày ở tầng 3."},{"jp":"すみません、時計の**売り場**はどこですか。","vi":"Xin lỗi, quầy bán đồng hồ ở đâu ạ?"}],
