  "67": [{"jp":"**地下**に駐車場があります。","vi":"Ở tầng hầm có bãi đỗ xe."},{"jp":"このデパートの**地下**1階は食料品売り場です。","vi":"Tầng hầm 1 của trung tâm thương mại này là quầy bán thực phẩm."}],
  "68": [{"jp":"私の部屋は**5階**です。","vi":"Phòng của tôi ở tầng 5."},{"jp":"会議室は**3階**にあります。","vi":"Phòng họp ở tầng 3."}],
