  "70": [{"jp":"このりんごは**100円**です。","vi":"Quả táo này 100 yên."},{"jp":"コーヒーは**300円**でした。","vi":"Cà phê có giá 300 yên."}],
  "71": [{"jp":"この時計は**幾ら**ですか。","vi":"Chiếc đồng hồ này bao nhiêu tiền?"},{"jp":"「このかばんは**幾ら**ですか。」「5000円です。」","vi":"\"Cái cặp này bao nhiêu tiền?\" \"5000 yên.\""}],
  "72": [{"jp":"このペンは**百**円です。","vi":"Cái bút này 100 yên."},{"jp":"教室に学生が**百**人います。","vi":"Trong phòng học có 100 học sinh."}],
  "73": [{"jp":"この本は**千**円です。","vi":"Quyển sách này 1000 yên."},{"jp":"この町には**千**人ぐらい住んでいます。","vi":"Thị trấn này có khoảng 1000 người sinh sống."}],
  "74": [{"jp":"このパソコンは10**万**円です。","vi":"Cái máy tính này 100.000 yên."},{"jp":"毎月3**万**円貯金しています。","vi":"Mỗi tháng tôi tiết kiệm 30.000 yên."}],
  "75": [{"jp":"毎朝6時に**起きます**。","vi":"Mỗi sáng tôi thức dậy lúc 6 giờ."},{"jp":"今朝は遅く**起きました**。","vi":"Sáng nay tôi dậy muộn."}],
  "76": [{"jp":"毎晩11時に**寝ます**。","vi":"Tối nào tôi cũng ngủ lúc 11 giờ."},{"jp":"疲れたので、早く**寝ました**。","vi":"Vì mệt nên tôi đã ngủ sớm."}],
